"""Restore incidental historical .pyc bytes regenerated by isolated child tests."""
import hashlib
import json
from pathlib import Path
import zipfile

ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent
REPORT = HERE / 'demo_support_posttest_cache_restoration.json'


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


if REPORT.exists():
    raise SystemExit('Cache restoration already recorded.')
plan = json.loads((HERE / 'demo_support_move_plan.json').read_text())
recovery = json.loads((HERE / 'demo_support_recovery.json').read_text())
archive = Path(recovery['archive'])
assert sha(archive.read_bytes()) == recovery['sha256']
changes = []
with zipfile.ZipFile(archive) as source:
    for row in plan['entries']:
        if not row['destination_relative_path'].endswith('.pyc'):
            continue
        path = ROOT / row['destination_relative_path']
        assert path.resolve().is_relative_to(ROOT / 'pilots/anomalon_woland_support')
        current = path.read_bytes()
        if sha(current) == row['sha256']:
            continue
        original = source.read(row['source_repo'] + '/' + row['source_relative_path'])
        assert sha(original) == row['sha256']
        saved = HERE / 'generated_cache_before_restoration' / (sha(current) + '.bin')
        saved.parent.mkdir(exist_ok=True)
        with saved.open('xb') as handle:
            handle.write(current)
        path.write_bytes(original)
        assert sha(path.read_bytes()) == row['sha256']
        changes.append({'path': row['destination_relative_path'], 'generated_sha256': sha(current),
                        'restored_original_sha256': row['sha256'], 'generated_bytes_preserved': str(saved)})
REPORT.write_text(json.dumps({'reason': 'The original calibration tests launch Python with -I; that ignores PYTHONDONTWRITEBYTECODE and regenerates three incidental caches. Restore original moved bytes after tests; source and recorded campaign data were unchanged.',
                             'changes': changes}, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'restored_incidental_caches': len(changes)}))
